import React from 'react';
import './Sidebar.css';

import ''
const Sidebar: React.FC<SidebarProps> = ({ activeMenuItem, onMenuItemClick }) => {
  const menuItems = [
    'Home',
    'Add Hotel',
    'Properties',
    'Room & Rateplan',
    'Room Allocated Count',
    'Inventory',
  ];

  return (
    <div className="sidebar">
      <div className="barcode-strip"></div>
      <ul className="menu-list">
        {menuItems.map((item) => (
          <li
            key={item}
            className={activeMenuItem === item ? 'active-menu-item' : ''}
            onClick={() => onMenuItemClick(item)}
          >
            {item}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Sidebar;
